children.text:
.container {
    width: 20px;
    height: 20px;
    margin: 5px;
    border: 1px solid black;
}
canvas {
    height: -webkit-fill-available;
    height: stretch;
    background: purple;
}

.withBorder {
    border: 2px solid cyan;
    border-width: 2px 3px 4px 5px;
}
.withPadding {
    padding: 2px 3px 4px 5px;
}
.withPxMargin {
    margin: 1px 2px 3px 4px;
}
.withPctMargin {
    /* This works out to 1px 2px 3px 4px */
    margin: 5% 10% 15% 20%;
}
